#if LOCAL_SCENE3_AUDIT
using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
[InitializeOnLoad]public static class GuiziAudit{static double next;static GuiziAudit(){EditorApplication.update+=Tick;}static void Tick(){if(EditorApplication.timeSinceStartup<next)return;next=EditorApplication.timeSinceStartup+3;if(File.Exists("D:/-11-scene3-audit/guizi-unity.txt")||EditorApplication.isCompiling||EditorApplication.isUpdating)return;var s=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(s.name!="scene3")return;var rows=new List<string>();foreach(var r in s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).Where(r=>r.name=="guizi1"||r.name=="guizi2")){var mf=r.GetComponent<MeshFilter>();rows.Add("OBJECT|"+r.name+"|mesh="+(mf&&mf.sharedMesh?mf.sharedMesh.name:"")+"|position="+r.bounds.center+"|size="+r.bounds.size);foreach(var m in r.sharedMaterials){rows.Add("MAT|"+AssetDatabase.GetAssetPath(m)+"|shader="+m.shader.name);foreach(var prop in new[]{"_Color","_Metallic","_Roughness","_UseMetal","_UseRough","_EmissionColor","_NormalStrength"})if(m.HasProperty(prop))rows.Add(prop+"="+(prop.Contains("Color")?m.GetColor(prop).ToString():m.GetFloat(prop).ToString()));foreach(var prop in new[]{"_MainTex","_MetalTex","_RoughTex","_BumpMap"})if(m.HasProperty(prop))rows.Add(prop+"="+AssetDatabase.GetAssetPath(m.GetTexture(prop)));}}if(rows.Count>0)File.WriteAllLines("D:/-11-scene3-audit/guizi-unity.txt",rows);}}

#endif
